  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.container {
  width: 100%;
  max-width: 500px;
}

.contact-form-wrapper {
  background: #1e1e1e;
  border: 1px solid #333;
  border-radius: 12px;
  padding: 40px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.form-header {
  margin-bottom: 32px;
  text-align: center;
}

.form-header h1 {
  font-size: 28px;
  font-weight: 600;
  color: #ffffff;
  margin-bottom: 8px;
  letter-spacing: -0.5px;
}

.form-header p {
  font-size: 14px;
  color: #a0a0a0;
  line-height: 1.5;
}

.contact-form {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.form-field label {
  font-size: 14px;
  font-weight: 500;
  color: #ffffff;
  letter-spacing: 0.3px;
}

.form-field input {
  padding: 12px 16px;
  background: #2a2a2a;
  border: 1px solid #404040;
  border-radius: 8px;
  color: #e0e0e0;
  font-size: 14px;
  transition: all 0.2s ease;
  font-family: inherit;
}

.form-field input::placeholder {
  color: #606060;
}

.form-field input:focus {
  outline: none;
  border-color: #4a9eff;
  background: #2f2f2f;
  box-shadow: 0 0 0 3px rgba(74, 158, 255, 0.1);
}

.form-field input.error {
  border-color: #ff6b6b;
  background: #2f2a2a;
}

.form-field input.error:focus {
  box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.1);
}

.helper-text {
  font-size: 12px;
  color: #808080;
  line-height: 1.4;
}

.error-message {
  font-size: 12px;
  color: #ff6b6b;
  min-height: 16px;
  line-height: 1.4;
}

.error-message.show {
  display: block;
}

.submit-button {
  padding: 12px 24px;
  background: linear-gradient(135deg, #4a9eff 0%, #357abd 100%);
  color: #ffffff;
  border: none;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  letter-spacing: 0.5px;
  margin-top: 8px;
  font-family: inherit;
}

.submit-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(74, 158, 255, 0.3);
}

.submit-button:active {
  transform: translateY(0);
}

.submit-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.success-message {
  margin-top: 24px;
  padding: 16px;
  background: #1a3a2a;
  border: 1px solid #2d5a45;
  border-radius: 8px;
  color: #4ade80;
  font-size: 14px;
  text-align: center;
  min-height: 0;
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  transition: all 0.3s ease;
