}

.success-message.show {
  min-height: 56px;
  max-height: 100px;
  opacity: 1;
}

@media (max-width: 480px) {
  .contact-form-wrapper {
    padding: 24px;
  }

  .form-header h1 {
    font-size: 24px;
  }

  .form-header p {
    font-size: 13px;
  }
}
